import org.davidmoten.text.utils.WordWrap;
import org.davidmoten.text.utils.WordWrap.Builder;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.StringReader;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;

public class WordWrapTests {

    @Test
    public void fromReaderTest() {
        StringReader reader = new StringReader("Test");
        Builder builder = WordWrap.from(reader);
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromClasspathUtf8Test() {
        Builder builder = WordWrap.fromClasspathUtf8("testResource");
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromClasspathTest() {
        Builder builder = WordWrap.fromClasspath("testResource", StandardCharsets.UTF_8);
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromCharSequenceTest() {
        Builder builder = WordWrap.from("Test Sequence");
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromUtf8Test() {
        Builder builder = WordWrap.fromUtf8(null);
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromInputStreamTest() {
        Builder builder = WordWrap.from(null, StandardCharsets.UTF_8);
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void fromFileTest() {
        Builder builder = WordWrap.from(null, StandardCharsets.UTF_8);
        assertNotNull("Builder object should not be null", builder);
    }

    @Test
    public void rightTrimTest() {
        CharSequence result = WordWrap.rightTrim("   test   ");
        assertEquals("test   ", result.toString());
    }

    @Test
    public void isWhitespaceTest() {
        assertTrue(WordWrap.isWhitespace("   "));
        assertFalse(WordWrap.isWhitespace("test"));
    }

    @Test
    public void wordWrapTest() throws IOException {
        StringWriter writer = new StringWriter();
        WordWrap.wordWrap(new StringReader("Test"), writer, "\n", 4, 
                          str -> str.length(), new HashSet<>(), false, false);
        assertEquals("Test", writer.toString());
    }

    @Test(expected = IOException.class)
    public void wordWrapIOExceptionTest() throws IOException {
        WordWrap.wordWrap(new BadReader(), new StringWriter(), "\n", 4, 
                          str -> str.length(), new HashSet<>(), false, false);
    }
}

class BadReader extends StringReader {
    BadReader() { super(""); }
    @Override public int read(char[] cbuf, int off, int len) throws IOException { throw new IOException(); }
}
